#!/usr/bin/env python3
"""Deterministic fixed-degree convolution; no field sampling or tuning."""

from pathlib import Path

from c_format import format_c

lines = [
    "/* Generated by tools/finite/generate_fields.py; do not edit. */",
    "/* Fixed-degree polynomial convolution in canonical prime residues.",
    " * Four canonical products fit: 4*(p-1)^2 < 2^64 for p < 2^31.",
    " * Each convolution chunk has at most four products; chunk residues",
    " * are added canonically. Reduction adds only two residues at once. */",
]
for d in range(1, 13):
    lines += [
        f"// Multiply polynomial-basis coefficients of degree {d}",
        f"static inline void fastcd_ff_product{d}(uint32_t* out,",
        "        const uint32_t* a, const uint32_t* b, const FastCDField* f) {",
    ]
    if d == 1:
        lines += ["    out[0] = fastcd_ff_mul(a[0], b[0], f);", "}"]
        continue
    lines += [f"    uint32_t t[{2 * d - 1}];"]
    for k in range(2 * d - 1):
        terms = [f"(uint64_t)a[{i}] * b[{k - i}]" for i in range(d) if 0 <= k - i < d]
        for start in range(0, len(terms), 4):
            expr = " + ".join(terms[start : start + 4])
            if start == 0:
                lines += [f"    t[{k}] = fastcd_ff_reduce({expr}, f);"]
            else:
                lines += [
                    f"    t[{k}] = fastcd_ff_add(t[{k}], fastcd_ff_reduce({expr}, f), f);"
                ]
    for k in range(2 * d - 2, d - 1, -1):
        for j in range(d):
            lines += [
                f"    if (f->negative[{j}] != 0) t[{k - d + j}] = fastcd_ff_add(t[{k - d + j}],",
                f"            fastcd_ff_mul(t[{k}], f->negative[{j}], f), f);",
            ]
    lines += [f"    for (size_t i = 0; i < {d}; i++) out[i] = t[i];", "}"]
Path(__file__).resolve().parents[2].joinpath(
    "src/finite/generated/field_products.h"
).write_text(format_c("\n".join(lines) + "\n"))
